// Nibfin job-started hook, check step. Generated by gh nibfin runner add; do
// not edit. job-started.sh runs it as:
//   node check.mjs <hook dir> <fetched dir>
// with only the GITHUB_* values it needs in its environment. It lets a Job
// run only when the workflow that started it is the execution repository's
// nibfin-shared-runner.yml, the dispatch assignee is the Runner's owner, that
// file and nibfin-job.yml at GITHUB_WORKFLOW_SHA match the official files
// runner add installed (rendered by the Nibfin image) except the image digest
// and the one commit they call nibfin-core's Action at, the digest carries a
// Sigstore-signed attestation by nibfin-core's image.yml on main, built on a
// GitHub-hosted runner, and that attestation's source commit is the Action
// commit. It exits 0 when every check passes, else 1 with the reason. It uses
// only node: built-ins and never prints a file's content.

import { X509Certificate, createHash, createPublicKey, verify } from "node:crypto";
import { readFileSync } from "node:fs";
import { join } from "node:path";

// The image policy; internal/runnerhook's tests keep it equal to
// internal/image's.
const IMAGE_REPOSITORY = "ghcr.io/taco3064/nibfin";
const SOURCE_REPO = "taco3064/nibfin-core";
const SIGNER_URI = `https://github.com/${SOURCE_REPO}/.github/workflows/image.yml@refs/heads/main`;
const SOURCE_REPO_URI = `https://github.com/${SOURCE_REPO}`;
const SOURCE_REF = "refs/heads/main";
const OIDC_ISSUER = "https://token.actions.githubusercontent.com";
const RUNNER_ENVIRONMENT = "github-hosted";

const SHARED = "nibfin-shared-runner.yml";
const JOB = "nibfin-job.yml";
const PLACEHOLDER = "0".repeat(64);
const IMAGE_LINE = /^  IMAGE_REF: ghcr\.io\/taco3064\/nibfin@sha256:([0-9a-f]{64})$/;
// A call of nibfin-core's Action (SOURCE_REPO) pinned to a full commit; the
// official files carry PLACEHOLDER_COMMIT there.
const ACTION_REF = /(uses: taco3064\/nibfin-core\/action@)([0-9a-f]{40})/g;
const PLACEHOLDER_COMMIT = "0".repeat(40);
const TIMEOUT_MS = 30000;

// The steps a refusal names.
const NEXT_TEMPLATE = "the Owner runs gh nibfin upgrade; if it is current, run gh nibfin runner add again, which renders the official files from the latest image";
const NEXT_TRUST = "update gh-nibfin and run gh nibfin runner add again";
const NEXT_READD = "run gh nibfin runner remove, then gh nibfin runner add";
const NEXT_RERUN = "run the Job again later";

class Refusal extends Error {
  constructor(reason, next) {
    super(reason);
    this.next = next;
  }
}

function refuse(reason, next) {
  throw new Refusal(reason, next);
}

// readConfig reads the key=value lines of the hook's config.
function readConfig(dir) {
  const out = {};
  for (const line of readFileSync(join(dir, "config"), "utf8").split("\n")) {
    const i = line.indexOf("=");
    if (i > 0) out[line.slice(0, i)] = line.slice(i + 1);
  }
  return out;
}

function b64(s, what) {
  if (typeof s !== "string" || !/^[A-Za-z0-9+/]*={0,2}$/.test(s)) refuse(`${what} is not base64`);
  return Buffer.from(s, "base64");
}

// get fetches url without credentials, bounded by TIMEOUT_MS.
async function get(url, what) {
  try {
    const res = await fetch(url, {
      headers: { "User-Agent": "nibfin-runner-hook", Accept: "application/vnd.github+json" },
      redirect: "error",
      signal: AbortSignal.timeout(TIMEOUT_MS),
    });
    return { status: res.status, body: Buffer.from(await res.arrayBuffer()) };
  } catch (e) {
    const why = e && e.name === "TimeoutError" ? `no answer within ${TIMEOUT_MS / 1000} s` : String((e && e.cause && e.cause.message) || (e && e.message) || e);
    refuse(`cannot read ${what}: ${why}`, NEXT_RERUN);
  }
}

// --- The workflow, the event and the files -------------------------------

function checkWorkflowRef(cfg, env) {
  const ref = env.GITHUB_WORKFLOW_REF || "";
  const m = /^([^/@]+)\/([^/@]+)\/\.github\/workflows\/([^@]+)@(.+)$/.exec(ref);
  const owner = cfg.owner.toLowerCase();
  const name = cfg.name.toLowerCase();
  if (!m || m[1].toLowerCase() !== owner || m[2].toLowerCase() !== name || m[3] !== SHARED) {
    refuse(`the Job was started by ${JSON.stringify(ref)}, not ${cfg.owner}/${cfg.name}/.github/workflows/${SHARED}`,
      `only official Nibfin Jobs for ${cfg["user-id"]} run on this Runner`);
  }
}

function checkEvent(cfg, env) {
  if (env.GITHUB_EVENT_NAME !== "workflow_dispatch") {
    refuse(`the Job was started by a ${JSON.stringify(env.GITHUB_EVENT_NAME || "")} event, not workflow_dispatch`,
      `only official Nibfin Jobs for ${cfg["user-id"]} run on this Runner`);
  }
  let event;
  try {
    event = JSON.parse(readFileSync(env.GITHUB_EVENT_PATH || "", "utf8"));
  } catch (e) {
    refuse(`cannot read the event payload: ${e.message}`);
  }
  const assignee = event && event.inputs ? event.inputs.assignee : undefined;
  if (typeof assignee !== "string" || assignee !== cfg["user-id"]) {
    refuse(`the Job is dispatched for assignee ${JSON.stringify(assignee === undefined ? "" : assignee)}, not ${cfg["user-id"]}`,
      `only official Nibfin Jobs for ${cfg["user-id"]} run on this Runner`);
  }
}

async function readFiles(cfg, sha, fetched, rawBase) {
  const out = {};
  for (const f of [SHARED, JOB]) {
    if (cfg.private === "1") {
      try {
        out[f] = readFileSync(join(fetched, f));
      } catch (e) {
        refuse(`cannot read .github/workflows/${f} at ${sha}: ${e.code || e.message}`);
      }
      continue;
    }
    const where = `${cfg.owner}/${cfg.name}@${sha}:.github/workflows/${f}`;
    const r = await get(`${rawBase}/${cfg.owner}/${cfg.name}/${sha}/.github/workflows/${f}`, where);
    if (r.status === 404) {
      refuse(`${where} is not readable without a credential (HTTP 404): the file is missing or the repository is private`,
        `if the repository became private, ${NEXT_READD}`);
    }
    if (r.status !== 200) refuse(`cannot read ${where}: HTTP ${r.status}`, NEXT_RERUN);
    out[f] = r.body;
  }
  return out;
}

// checkTemplates compares the files with the official ones and returns the
// image digest of nibfin-job.yml and the one commit the files call
// nibfin-core's Action at (null when the official files call no Action).
// Each file is compared byte for byte (latin1 maps bytes one to one) after
// its Action commit becomes PLACEHOLDER_COMMIT and, in nibfin-job.yml, its
// one IMAGE_REF digest becomes PLACEHOLDER.
function checkTemplates(hook, files) {
  const official = (f) => readFileSync(join(hook, "official", f)).toString("latin1");
  const commits = new Set();
  let officialCalls = 0;
  const text = {};
  for (const f of [SHARED, JOB]) {
    const t = files[f].toString("latin1");
    for (const m of t.matchAll(ACTION_REF)) commits.add(m[2]);
    officialCalls += [...official(f).matchAll(ACTION_REF)].length;
    text[f] = t.replace(ACTION_REF, `$1${PLACEHOLDER_COMMIT}`);
  }
  if (commits.size > 1) {
    refuse(`the workflow files call ${SOURCE_REPO}'s Action at ${commits.size} commits, not one`, NEXT_TEMPLATE);
  }
  if (officialCalls === 0 && commits.size > 0) {
    refuse(`the workflow files call ${SOURCE_REPO}'s Action, which the official files do not`, NEXT_TEMPLATE);
  }
  if (text[SHARED] !== official(SHARED)) {
    refuse(`.github/workflows/${SHARED} differs from the official template runner add installed`, NEXT_TEMPLATE);
  }
  const lines = text[JOB].split("\n");
  const at = [];
  lines.forEach((l, i) => {
    if (IMAGE_LINE.test(l)) at.push(i);
  });
  if (at.length !== 1) {
    refuse(`.github/workflows/${JOB} has ${at.length} IMAGE_REF lines naming ${IMAGE_REPOSITORY}@sha256:<digest>, not one`, NEXT_TEMPLATE);
  }
  const digest = IMAGE_LINE.exec(lines[at[0]])[1];
  lines[at[0]] = `  IMAGE_REF: ${IMAGE_REPOSITORY}@sha256:${PLACEHOLDER}`;
  if (lines.join("\n") !== official(JOB)) {
    refuse(`.github/workflows/${JOB} differs from the official template runner add installed`, NEXT_TEMPLATE);
  }
  return { digest, commit: commits.size === 1 ? [...commits][0] : null };
}

// --- DER ---------------------------------------------------------------

// tlv reads one DER element of buf at i.
function tlv(buf, i) {
  if (i + 2 > buf.length) throw new Error("truncated DER");
  const tag = buf[i];
  if ((tag & 0x1f) === 0x1f) throw new Error("unsupported DER tag");
  let len = buf[i + 1];
  let start = i + 2;
  if (len & 0x80) {
    const n = len & 0x7f;
    if (n === 0 || n > 4 || start + n > buf.length) throw new Error("bad DER length");
    len = 0;
    for (let k = 0; k < n; k++) len = len * 256 + buf[start + k];
    start += n;
  }
  const end = start + len;
  if (end > buf.length) throw new Error("truncated DER");
  return { tag, start, end };
}

function children(buf, el) {
  const out = [];
  for (let i = el.start; i < el.end; ) {
    const c = tlv(buf, i);
    out.push(c);
    i = c.end;
  }
  return out;
}

function oid(bytes) {
  const parts = [Math.floor(bytes[0] / 40), bytes[0] % 40];
  let v = 0;
  for (let k = 1; k < bytes.length; k++) {
    v = v * 128 + (bytes[k] & 0x7f);
    if (!(bytes[k] & 0x80)) {
      parts.push(v);
      v = 0;
    }
  }
  return parts.join(".");
}

// extensions returns the certificate's extensions by OID, each value the
// content of its OCTET STRING.
function extensions(der) {
  const cert = tlv(der, 0);
  const tbs = children(der, cert)[0];
  const out = {};
  for (const f of children(der, tbs)) {
    if (f.tag !== 0xa3) continue;
    const seq = children(der, f)[0];
    for (const ext of children(der, seq)) {
      const parts = children(der, ext);
      const id = oid(der.subarray(parts[0].start, parts[0].end));
      const value = parts[parts.length - 1];
      if (value.tag !== 0x04) throw new Error("bad extension value");
      out[id] = der.subarray(value.start, value.end);
    }
  }
  return out;
}

// utf8Ext decodes a Fulcio extension (1.3.6.1.4.1.57264.1.8 and above): a
// DER UTF8String.
function utf8Ext(exts, id) {
  const v = exts[id];
  if (!v) return undefined;
  const el = tlv(v, 0);
  if (el.tag !== 0x0c || el.end !== v.length) throw new Error(`extension ${id} is not a UTF8String`);
  return v.subarray(el.start, el.end).toString("utf8");
}

// --- Sigstore ------------------------------------------------------------

function cert(der, what) {
  try {
    return new X509Certificate(der);
  } catch (e) {
    refuse(`${what} is not a certificate: ${e.message}`);
  }
}

function within(t, validFor) {
  const start = validFor && validFor.start ? Date.parse(validFor.start) : NaN;
  const end = validFor && validFor.end ? Date.parse(validFor.end) : Infinity;
  return !Number.isNaN(start) && start <= t && t <= end;
}

function certWithin(c, t) {
  return Date.parse(c.validFrom) <= t && t <= Date.parse(c.validTo);
}

// hashFor is the digest an ECDSA key signs with; null for Ed25519.
function hashFor(key) {
  if (key.asymmetricKeyType === "ed25519") return null;
  const curve = key.asymmetricKeyDetails && key.asymmetricKeyDetails.namedCurve;
  if (key.asymmetricKeyType === "ec" && curve === "prime256v1") return "sha256";
  if (key.asymmetricKeyType === "ec" && curve === "secp384r1") return "sha384";
  refuse(`the signing key type ${key.asymmetricKeyType} ${curve || ""} is not supported`, NEXT_TRUST);
}

function digits(s, what) {
  if (typeof s !== "string" || !/^(0|[1-9][0-9]{0,18})$/.test(s)) refuse(`${what} is not a number`);
  return s;
}

// verifyBundle checks one attestation bundle against the trusted root and
// the policy; it throws a Refusal at the first failed check.
function verifyBundle(bundle, root, digest, commit) {
  if (!bundle || bundle.mediaType !== "application/vnd.dev.sigstore.bundle.v0.3+json") {
    refuse(`the bundle media type ${JSON.stringify(bundle && bundle.mediaType)} is not a Sigstore bundle v0.3`, NEXT_TRUST);
  }
  const vm = bundle.verificationMaterial || {};
  if (!vm.certificate || !vm.certificate.rawBytes) refuse("the bundle has no signing certificate", NEXT_TRUST);
  const leafDER = b64(vm.certificate.rawBytes, "the signing certificate");
  const leaf = cert(leafDER, "the signing certificate");
  const env = bundle.dsseEnvelope || {};
  const sigs = Array.isArray(env.signatures) ? env.signatures : [];
  if (sigs.length !== 1) refuse(`the envelope has ${sigs.length} signatures, not one`);
  const sig = b64(sigs[0].sig, "the envelope signature");
  const payload = b64(env.payload, "the envelope payload");

  // Transparency-log time: a signed entry timestamp from a trusted log.
  const entries = Array.isArray(vm.tlogEntries) ? vm.tlogEntries : [];
  let t, entry, unknown = true;
  for (const e of entries) {
    const keyId = e && e.logId ? e.logId.keyId : undefined;
    const log = (root.tlogs || []).find((l) => l.logId && l.logId.keyId === keyId);
    if (!log || !log.publicKey || log.publicKey.keyDetails !== "PKIX_ECDSA_P256_SHA_256" || !e.inclusionPromise) continue;
    unknown = false;
    const key = createPublicKey({ key: b64(log.publicKey.rawBytes, "the log key"), format: "der", type: "spki" });
    const it = digits(e.integratedTime, "the entry time");
    const li = digits(e.logIndex, "the entry index");
    if (typeof e.canonicalizedBody !== "string") refuse("the log entry has no body");
    const signed = `{"body":${JSON.stringify(e.canonicalizedBody)},"integratedTime":${it},"logID":"${b64(keyId, "the log id").toString("hex")}","logIndex":${li}}`;
    if (!verify("sha256", Buffer.from(signed), key, b64(e.inclusionPromise.signedEntryTimestamp, "the entry timestamp"))) {
      refuse("the log entry timestamp does not verify with the log's key");
    }
    t = Number(it) * 1000;
    if (!within(t, log.publicKey.validFor)) refuse("the log entry lies outside the log key's validity");
    entry = e;
    break;
  }
  if (!entry) {
    refuse(unknown ? "the image signature uses a log or CA this hook does not know" : "the log entry has no signed entry timestamp", NEXT_TRUST);
  }

  // Certificate chain, at time T.
  let chained = false, known = false;
  for (const ca of root.certificateAuthorities || []) {
    if (!within(t, ca.validFor)) continue;
    const chain = ((ca.certChain && ca.certChain.certificates) || []).map((c) => cert(b64(c.rawBytes, "a CA certificate"), "a CA certificate"));
    if (chain.length === 0 || !leaf.checkIssued(chain[0])) continue;
    known = true;
    let ok = leaf.verify(chain[0].publicKey);
    for (let i = 0; ok && i < chain.length; i++) {
      const next = chain[i + 1] || chain[i];
      ok = chain[i].ca && chain[i].checkIssued(next) && chain[i].verify(next.publicKey) && certWithin(chain[i], t);
    }
    if (ok) {
      chained = true;
      break;
    }
  }
  if (!known) refuse("the image signature uses a log or CA this hook does not know: the signing certificate was not issued by a known Sigstore CA", NEXT_TRUST);
  if (!chained) refuse("the signing certificate does not verify against the Sigstore CA");
  if (!certWithin(leaf, t)) refuse("the signature was logged outside the signing certificate's validity");

  // The log entry binds this signature, payload and certificate.
  let body;
  try {
    body = JSON.parse(b64(entry.canonicalizedBody, "the log entry body").toString("utf8"));
  } catch (e) {
    refuse(`the log entry body is not JSON: ${e.message}`);
  }
  if (!entry.kindVersion || entry.kindVersion.kind !== "dsse" || !body || body.kind !== "dsse" || !body.spec) {
    refuse("the log entry is not a dsse entry", NEXT_TRUST);
  }
  const spec = body.spec;
  const payloadHash = createHash("sha256").update(payload).digest("hex");
  if (!spec.payloadHash || spec.payloadHash.algorithm !== "sha256" || spec.payloadHash.value !== payloadHash) {
    refuse("the log entry names another payload");
  }
  const logged = Array.isArray(spec.signatures) ? spec.signatures : [];
  if (logged.length !== 1 || !b64(logged[0].signature, "the logged signature").equals(sig)) {
    refuse("the log entry names another signature");
  }
  let verifier;
  try {
    verifier = new X509Certificate(b64(logged[0].verifier, "the logged verifier"));
  } catch {
    refuse("the log entry's verifier is not a certificate");
  }
  if (!verifier.raw.equals(leaf.raw)) refuse("the log entry names another certificate");

  // DSSE signature.
  if (env.payloadType !== "application/vnd.in-toto+json") refuse(`the payload type ${JSON.stringify(env.payloadType)} is not in-toto`);
  const type = Buffer.from(env.payloadType, "utf8");
  const pae = Buffer.concat([Buffer.from(`DSSEv1 ${type.length} `), type, Buffer.from(` ${payload.length} `), payload]);
  if (!verify(hashFor(leaf.publicKey), pae, leaf.publicKey, sig)) refuse("the signature does not verify");

  // Signer identity.
  let exts;
  try {
    exts = extensions(leaf.raw);
  } catch (e) {
    refuse(`cannot read the signing certificate's extensions: ${e.message}`);
  }
  const ext = (n) => {
    try {
      return utf8Ext(exts, `1.3.6.1.4.1.57264.1.${n}`);
    } catch (e) {
      refuse(e.message);
    }
  };
  const issuer = ext(8);
  if (issuer !== OIDC_ISSUER) refuse(`the signer's issuer is ${JSON.stringify(issuer || "")}, want ${OIDC_ISSUER}`);
  const signer = ext(9);
  if (signer !== SIGNER_URI) refuse(`signer is ${JSON.stringify(signer || "")}, want ${SIGNER_URI}`);
  if (leaf.subjectAltName !== `URI:${SIGNER_URI}`) refuse(`the certificate names ${JSON.stringify(leaf.subjectAltName || "")}, want ${SIGNER_URI}`);
  const repo = ext(12);
  if (repo !== SOURCE_REPO_URI) refuse(`the signer's repository is ${JSON.stringify(repo || "")}, want ${SOURCE_REPO_URI}`);
  const ref = ext(14);
  if (ref !== SOURCE_REF) refuse(`the signer's ref is ${JSON.stringify(ref || "")}, want ${SOURCE_REF}`);
  const runner = ext(11);
  if (runner !== RUNNER_ENVIRONMENT) refuse(`the image was built on a ${JSON.stringify(runner || "")} runner, want ${RUNNER_ENVIRONMENT}`);
  // The Action code the files run is the image's own: extension 13, the
  // Source Repository Digest, is the commit the image was built from.
  if (commit !== null) {
    const source = ext(13);
    if (source !== commit) {
      refuse(`the Action commit ${commit} is not the image's source commit ${JSON.stringify(source || "")}`, NEXT_TEMPLATE);
    }
  }

  // Statement.
  let st;
  try {
    st = JSON.parse(payload.toString("utf8"));
  } catch (e) {
    refuse(`the statement is not JSON: ${e.message}`);
  }
  if (!st || st._type !== "https://in-toto.io/Statement/v1") refuse("the statement is not an in-toto Statement v1");
  if (st.predicateType !== "https://slsa.dev/provenance/v1") refuse(`the predicate type ${JSON.stringify(st.predicateType)} is not SLSA provenance v1`);
  const subjects = Array.isArray(st.subject) ? st.subject : [];
  if (!subjects.some((s) => s && s.name === IMAGE_REPOSITORY && s.digest && s.digest.sha256 === digest)) {
    refuse(`the statement does not name ${IMAGE_REPOSITORY}@sha256:${digest}`);
  }
}

async function checkImage(digest, commit, apiBase) {
  const what = `the attestations of ${IMAGE_REPOSITORY}@sha256:${digest}`;
  const r = await get(`${apiBase}/repos/${SOURCE_REPO}/attestations/sha256:${digest}`, what);
  if (r.status === 404) refuse(`${IMAGE_REPOSITORY}@sha256:${digest} has no attestation in ${SOURCE_REPO} (HTTP 404)`, NEXT_TEMPLATE);
  if (r.status === 403 || r.status === 429) {
    refuse(`cannot read ${what}: HTTP ${r.status}; GitHub allows 60 unauthenticated API requests per hour per IP address`, NEXT_RERUN);
  }
  if (r.status !== 200) refuse(`cannot read ${what}: HTTP ${r.status}`, NEXT_RERUN);
  let list;
  try {
    list = JSON.parse(r.body.toString("utf8")).attestations;
  } catch (e) {
    refuse(`${what} are not JSON: ${e.message}`, NEXT_RERUN);
  }
  if (!Array.isArray(list) || list.length === 0) refuse(`${IMAGE_REPOSITORY}@sha256:${digest} has no attestation`, NEXT_TEMPLATE);
  const root = JSON.parse(readFileSync(join(hook, "trusted_root.json"), "utf8"));
  let last;
  for (const a of list) {
    try {
      verifyBundle(a && a.bundle, root, digest, commit);
      return;
    } catch (e) {
      if (!(e instanceof Refusal)) throw e;
      last = e;
    }
  }
  refuse(`the image attestation is not a valid official signature: ${last.message}`, last.next || `only official Nibfin images run on this Runner`);
}

// --- Main ----------------------------------------------------------------

const [hook, fetched] = process.argv.slice(2);
const env = process.env;

async function main() {
  const cfg = readConfig(hook);
  for (const k of ["owner", "name", "user-id", "private"]) {
    if (!cfg[k]) refuse(`the hook config has no ${k}`, NEXT_READD);
  }
  const base = cfg["test-base-url"];
  const apiBase = base ? `${base}/api` : "https://api.github.com";
  const rawBase = base ? `${base}/raw` : "https://raw.githubusercontent.com";
  const sha = env.GITHUB_WORKFLOW_SHA || "";
  checkWorkflowRef(cfg, env);
  checkEvent(cfg, env);
  const files = await readFiles(cfg, sha, fetched, rawBase);
  const { digest, commit } = checkTemplates(hook, files);
  await checkImage(digest, commit, apiBase);
  console.log(`Nibfin hook: accepted ${cfg.owner}/${cfg.name}@${sha}, image sha256:${digest}`);
}

main().then(
  () => process.exit(0),
  (e) => {
    if (e instanceof Refusal) {
      console.log(`Nibfin hook: refused: ${e.message}.${e.next ? ` ${e.next[0].toUpperCase()}${e.next.slice(1)}.` : ""}`);
    } else {
      console.log(`Nibfin hook: refused: the check failed: ${e && e.message ? e.message : e}.`);
    }
    process.exit(1);
  },
);
